class Solution:
    def checkIfCanBreak(self, s1: str, s2: str) -> bool:
        a, b = sorted(s1), sorted(s2)
        w1 = all(x >= y for x, y in zip(a, b))
        w2 = all(y >= x for x, y in zip(a, b))
        return w1 or w2

