class Solution {
public:
    bool checkIfCanBreak(string s1, string s2) {
        sort(s1.begin(), s1.end());
        sort(s2.begin(), s2.end());
        bool w1 = true, w2 = true;
        for (int i = 0; i < (int)s1.size(); ++i) {
            if (s1[i] < s2[i]) w1 = false;
            if (s2[i] < s1[i]) w2 = false;
        }
        return w1 || w2;
    }
};

