class Solution {
public:
    bool checkIfCanBreak(string s1, string s2) {
        int c1[26] = {0}, c2[26] = {0};
        for (char ch : s1) c1[ch - 'a']++;
        for (char ch : s2) c2[ch - 'a']++;
        int r1 = 0, r2 = 0, dir = 0;
        for (int i = 0; i < 26; i++) {
            r1 += c1[i]; r2 += c2[i];
            if (r1 > r2) { if (dir == 2) return false; dir = 1; }
            else if (r2 > r1) { if (dir == 1) return false; dir = 2; }
        }
        return true;
    }
};

